namespace Captovix;
public static class CaptureKeys
{
    public static bool IsSupported(uint key)=>key is >=0x08 and <=0xFE && key is not (0x10 or 0x11 or 0x12 or 0x5B or 0x5C or >=0xA0 and <=0xA5);
    public static bool IsValid(uint modifiers,uint key)=>(modifiers&~15u)==0&&IsSupported(key);
    public static string KeyName(uint key)=>key switch{>=0x30 and <=0x39 or >=0x41 and <=0x5A=>((char)key).ToString(),>=0x70 and <=0x87=>$"F{key-0x6F}",0x08=>"Backspace",0x09=>"Tab",0x0D=>"Enter",0x1B=>"Esc",0x20=>"Space",0x21=>"Page Up",0x22=>"Page Down",0x23=>"End",0x24=>"Home",0x25=>"←",0x26=>"↑",0x27=>"→",0x28=>"↓",0x2D=>"Insert",0x2E=>"Delete",0x2C=>"PrtSc",>=0x60 and <=0x69=>$"Num {key-0x60}",0x6A=>"Num *",0x6B=>"Num +",0x6D=>"Num -",0x6E=>"Num .",0x6F=>"Num /",0x14=>"Caps Lock",0x90=>"Num Lock",0x91=>"Scroll Lock",0x13=>"Pause",0xBA=>";",0xBB=>"=",0xBC=>",",0xBD=>"-",0xBE=>".",0xBF=>"/",0xC0=>"`",0xDB=>"[",0xDC=>"\\",0xDD=>"]",0xDE=>"'",0xDF or 0xE2=>$"OEM {key:X2}",_=>$"VK {key:X2}"};
}
